import re,os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def transform(g):
    import copy
    a=[row[:] for row in g]; H=len(a); W=len(a[0])
    twos=[(r,c) for r in range(H) for c in range(W) if a[r][c]==2]
    # horizontal: connect consecutive 2s in same row
    from collections import defaultdict
    rowsmap=defaultdict(list)
    for r,c in twos: rowsmap[r].append(c)
    for r,cs in rowsmap.items():
        cs=sorted(cs)
        for c1,c2 in zip(cs,cs[1:]):
            for c in range(c1+1,c2): a[r][c]=3
    # vertical: each 2 extends toward nearest 2 or 3 in column (post-horizontal)
    fills=[]
    for r,c in twos:
        # up
        rr=r-1
        while rr>=0 and a[rr][c]==0: rr-=1
        if rr>=0 and a[rr][c] in (2,3):
            for x in range(rr+1,r): fills.append((x,c))
        rr=r+1
        while rr<H and a[rr][c]==0: rr+=1
        if rr<H and a[rr][c] in (2,3):
            for x in range(r+1,rr): fills.append((x,c))
    for r,c in fills: a[r][c]=3
    return a

print(transform(G['Demo pair 1 input'])==G['Demo pair 1 output'])
